def seed_master_permissions():
    import uuid

    connection = op.get_bind()
    codes = [
        f"{resource}.{action}"
        for resource in ("customers", "projects", "items")
        for action in ("read", "create", "update", "archive")
    ]
    codes += [
        "lpos.read",
        "lpos.create",
        "lpos.update",
        "categories.manage",
        "units.manage",
        "families.manage",
        "images.manage",
    ]
    for code in codes:
        permission_id = uuid.uuid5(uuid.NAMESPACE_URL, f"urn:ambs:security:{code}")
        connection.execute(
            sa.text(
                "INSERT INTO permissions(id,code,description) VALUES (:id,:code,:description) ON CONFLICT(code) DO UPDATE SET description=excluded.description"
            ),
            {
                "id": permission_id,
                "code": code,
                "description": f"Phase 3 business master data: {code}",
            },
        )
    read = ["customers.read", "projects.read", "lpos.read", "items.read"]
    policies = {
        "SUPER_ADMIN": codes,
        "OPERATIONS": codes,
        "SALES": read,
        "ACCOUNTS": ["customers.read", "projects.read", "lpos.read"],
        "PACKING": ["items.read"],
        "MANAGEMENT": read,
        "DRIVER": [],
    }
    for role, grants in policies.items():
        for code in grants:
            connection.execute(
                sa.text(
                    "INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code=:role AND p.code=:code ON CONFLICT DO NOTHING"
                ),
                {"role": role, "code": code},
            )


def enforce_category_tree():
    op.execute("""
    CREATE FUNCTION ambs_check_category_tree() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      PERFORM pg_advisory_xact_lock(7140284201);
      IF NEW.parent_id IS NOT NULL AND EXISTS (
        WITH RECURSIVE ancestors AS (
          SELECT id,parent_id FROM product_categories WHERE id=NEW.parent_id
          UNION SELECT c.id,c.parent_id FROM product_categories c JOIN ancestors a ON c.id=a.parent_id
        ) SELECT 1 FROM ancestors WHERE id=NEW.id
      ) THEN RAISE EXCEPTION 'Category cycle' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER category_tree_integrity BEFORE INSERT OR UPDATE OF parent_id ON product_categories
    FOR EACH ROW EXECUTE FUNCTION ambs_check_category_tree();
    """)
